import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.qEx7tieT.js";const m=JSON.parse('{"title":"Edges","description":"","frontmatter":{},"headers":[],"relativePath":"guide/edges.md","filePath":"guide/edges.md"}'),n={name:"guide/edges.md"};function r(d,e,i,c,h,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="edges" tabindex="-1">Edges <a class="header-anchor" href="#edges" aria-label="Permalink to &quot;Edges&quot;">​</a></h1><p>Composing draws a building by its edges: the line where two faces meet at more than about thirty degrees — a corner, a reveal, the lip of a slab — which is what makes a plan or an elevation readable. Some geometry is not like that. A tree&#39;s faces meet at an angle everywhere, so edging one draws a black smudge where a tree should be.</p><p><code>core::edges</code> says so. <code>{&quot;draw&quot;: false}</code> on a node leaves it and everything beneath it unedged, so one component covers a whole model, and the nearest answer up the tree wins — a model can say no and one part of it say yes again. Left off entirely, edges are drawn.</p><p>It is worth saying where the component goes. A file that imports a tree can write <code>core::edges</code> onto the tree&#39;s own node, by id, without touching the archive that owns it: layering means the importing file has the last word. <code>examples/</code> aside, <code>sdk/cli/build/s1-together.mosaic.json</code> does exactly that for a tree, its trunk and a helmet.</p>',4)])])}const p=a(n,[["render",r]]);export{m as __pageData,p as default};
